<script setup lang="ts">import type { AnalyticsTemplate, AnalysisConfig } from "~/types/analytics"; const props=defineProps<{templates:AnalyticsTemplate[];modelValue:AnalysisConfig}>(); const emit=defineEmits<{select:[config:Partial<AnalysisConfig>]} >(); function select(event:Event){const value=(event.target as HTMLSelectElement).value; const template=props.templates.find((item)=>item.id===value);if(template)emit("select",template.config)}</script>
<template><label class="flex min-w-0 flex-col gap-1 text-sm font-medium">Templat analisis<select class="h-10 rounded-md border bg-background px-3" :value="templates.find((item)=>item.config.groupBy===modelValue.groupBy)?.id || ''" @change="select"><option value="">Pilih templat</option><option v-for="template in templates" :key="template.id" :value="template.id">{{ template.label }}</option></select></label></template>
